local CoinBlankMaker = {}
local PRODUCTS = {
    iron_coin_blank = { name = "Železni kovinski polizdelek", ironCost = 5, woodCost = 1, leatherCost = 1, time = 5, cost = 185, prestige = 4, happiness = 2, description = "Železni kovinski polizdelek za kovanje kovancev." },
    bronze_coin_blank = { name = "Bronast kovinski polizdelek", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 445, prestige = 6, happiness = 3, description = "Bronast kovinski polizdelek za fine kovance." },
    silver_coin_blank = { name = "Srebrni kovinski polizdelek", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1070, prestige = 11, happiness = 4, description = "Srebrni kovinski polizdelek za plemiške kovance." },
    gilded_coin_blank = { name = "Pozlačeni kovinski polizdelek", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2300, prestige = 20, happiness = 5, description = "Pozlačeni kovinski polizdelek za dvorne kovance." },
    jewel_set_coin_blank = { name = "Draguljasti kovinski polizdelek", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4950, prestige = 36, happiness = 7, description = "Draguljasti kovinski polizdelek za kraljevske kovance." },
    royal_sovereign_coin_blank = { name = "Kraljevski suvereni kovinski polizdelek", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10600, prestige = 69, happiness = 13, description = "Suvereni kovinski polizdelek z biseri za krono." },
}
local BUILDINGS = {
    coinblank_workshop = { name = "Polizdelna delavnica", cost = { gold = 375, wood = 175, stone = 150, iron = 10 }, upkeep = 7, qualityBonus = 5 },
    coinblank_house = { name = "Polizdelna hiša", cost = { gold = 1300, wood = 360, stone = 295, silver = 8, iron = 9 }, upkeep = 28, qualityBonus = 18 },
    master_coinblank_atelier = { name = "Mojstrski polizdelni atelje", cost = { gold = 3250, wood = 425, stone = 555, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_coinblank_palace = { name = "Suverena polizdelna palača", cost = { gold = 13850, wood = 660, stone = 875, gold = 89, jewel = 20 }, upkeep = 265, qualityBonus = 55, prestigeBonus = 50 },
}
CoinBlankMaker.ironStock = 18; CoinBlankMaker.bronzeStock = 14; CoinBlankMaker.woodStock = 10; CoinBlankMaker.leatherStock = 8; CoinBlankMaker.silverStock = 8; CoinBlankMaker.goldStock = 6; CoinBlankMaker.jewelStock = 4; CoinBlankMaker.pearlStock = 4
CoinBlankMaker.productStock = {}; CoinBlankMaker.buildings = {}; CoinBlankMaker.maker = nil; CoinBlankMaker.activeMaking = {}; CoinBlankMaker.totalProducts = 0; CoinBlankMaker.dayTimer = 0
function CoinBlankMaker.init() CoinBlankMaker.ironStock=18; CoinBlankMaker.bronzeStock=14; CoinBlankMaker.woodStock=10; CoinBlankMaker.leatherStock=8; CoinBlankMaker.silverStock=8; CoinBlankMaker.goldStock=6; CoinBlankMaker.jewelStock=4; CoinBlankMaker.pearlStock=4; CoinBlankMaker.productStock={}; CoinBlankMaker.buildings={}; CoinBlankMaker.maker=nil; CoinBlankMaker.activeMaking={}; CoinBlankMaker.totalProducts=0; CoinBlankMaker.dayTimer=0; print("[CoinBlankMaker] Royal Coin Blank Maker System initialized (6 products, 4 buildings)") end
function CoinBlankMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoinBlankMaker.maker={name=n or ("Polizdelkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polizdelkar najet: %s (spretnost: %d)",CoinBlankMaker.maker.name,s),"success") end; return true end
function CoinBlankMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoinBlankMaker.build(id) local ok,e=CoinBlankMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoinBlankMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoinBlankMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoinBlankMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoinBlankMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoinBlankMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoinBlankMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoinBlankMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoinBlankMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoinBlankMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoinBlankMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoinBlankMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoinBlankMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoinBlankMaker.buildings==0 then return false,"Potrebna polizdelna delavnica" end; if not CoinBlankMaker.maker then return false,"Potreben polizdelkar" end; return true end
function CoinBlankMaker.make(pt,qty) qty=qty or 1; local ok,e=CoinBlankMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoinBlankMaker.ironStock=CoinBlankMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoinBlankMaker.bronzeStock=CoinBlankMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoinBlankMaker.woodStock=CoinBlankMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoinBlankMaker.leatherStock=CoinBlankMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoinBlankMaker.silverStock=CoinBlankMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoinBlankMaker.goldStock=CoinBlankMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoinBlankMaker.jewelStock=CoinBlankMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoinBlankMaker.pearlStock=CoinBlankMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoinBlankMaker.maker then t=math.max(1,t-math.floor(CoinBlankMaker.maker.skill/13)) end; table.insert(CoinBlankMaker.activeMaking,{id="coinblank_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoinBlankMaker.completeMaking(m) local q=1.0+(CoinBlankMaker.getQualityBonus()/100); if CoinBlankMaker.maker then q=q+(CoinBlankMaker.maker.skill/140) end; q=math.min(2.5,q); CoinBlankMaker.productStock[m.productType]=(CoinBlankMaker.productStock[m.productType] or 0)+m.quantity; CoinBlankMaker.totalProducts=CoinBlankMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoinBlankMaker.maker then CoinBlankMaker.maker.itemsMade=CoinBlankMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoinBlankMaker.maker.skill=math.min(100,CoinBlankMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polizdelek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coinblank.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoinBlankMaker.update(dt) if not _G.state then return end; CoinBlankMaker.dayTimer=CoinBlankMaker.dayTimer+dt; if CoinBlankMaker.dayTimer>=30 then CoinBlankMaker.dayTimer=0; for i=#CoinBlankMaker.activeMaking,1,-1 do local m=CoinBlankMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoinBlankMaker.completeMaking(m); table.remove(CoinBlankMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoinBlankMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoinBlankMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoinBlankMaker.getStats() return {ironStock=CoinBlankMaker.ironStock,bronzeStock=CoinBlankMaker.bronzeStock,woodStock=CoinBlankMaker.woodStock,leatherStock=CoinBlankMaker.leatherStock,silverStock=CoinBlankMaker.silverStock,goldStock=CoinBlankMaker.goldStock,jewelStock=CoinBlankMaker.jewelStock,pearlStock=CoinBlankMaker.pearlStock,productStock=CoinBlankMaker.productStock,numBuildings=#CoinBlankMaker.buildings,hasMaker=CoinBlankMaker.maker~=nil,makerName=CoinBlankMaker.maker and CoinBlankMaker.maker.name or "—",makerSkill=CoinBlankMaker.maker and CoinBlankMaker.maker.skill or 0,activeMaking=#CoinBlankMaker.activeMaking,totalProducts=CoinBlankMaker.totalProducts} end
return CoinBlankMaker
